import java.util.function.*;
public class Main {
    public static void main(String[] args) {
        Function<String, String> f = s -> s.toUpperCase() + "!";
        Predicate<String> p = s -> s.length() > 5;
        String word = "magic";
        System.out.println(f.apply(word));
        System.out.println(p.test(word));
    }
}

